# BAD: N+1 queries
users = (await db.execute(select(User))).scalars().all()
for u in users:
    print(u.items)   # lazy loads each time — 1 query PER user

# GOOD: 2 queries total
users = (await db.execute(
    select(User).options(selectinload(User.items))
)).scalars().all()
for u in users:
    print(u.items)   # already loaded
